import {mixerCases,makeMixerSource,mixerCopy as T} from './rule-mixer-content.mjs';
import {newMixerWork,changeMixerWork,mixerDisplay,mixerDisplayPairs,mixerSheetsView,keepMixerSheet,recordMixerDisplay} from './rule-mixer-core.mjs';
import {fraction,formatNumber} from './equality-desk-content.mjs';
import {stopSpeech} from './play-media.mjs';
const clone=x=>structuredClone(x),visits=new WeakMap(),own=(x,k)=>Object.hasOwn(x,k);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const bytes=x=>{try{return JSON.stringify(x);}catch{return null;}};
const okOwner=x=>typeof x==='string'&&x.trim().length>0,route=()=>location.hash==='#learn/math/equality';
const num=x=>(typeof x==='number'?String(x):formatNumber(x)).replace(/^-/,'−');
const btn=(attr,text,primary=false)=>'<button type="button" class="'+(primary?'primary':'secondary')+'" '+attr+'>'+esc(text)+'</button>';
const span=(lo,hi)=>Array.from({length:hi-lo+1},(_,i)=>lo+i);
const select=(attr,label,values,value,format=x=>num(x),disabled=false)=>'<label>'+esc(label)+'<select '+attr+(disabled?' disabled':'')+'>'+values.map(x=>'<option value="'+esc(x)+'"'+(x===value?' selected':'')+'>'+esc(format(x))+'</option>').join('')+'</select></label>';
const sayNumber=q=>typeof q==='number'?(q<0?'negative '+Math.abs(q):String(q)):(q.n<0?'negative ':'')+Math.abs(q.n)+(q.d===1?'':' over '+q.d);
const words=text=>String(text).replace(/ − /g,' minus ').replace(/−/g,' negative ').replace(/×/g,' times ').replace(/=/g,' equals ').replace(/\+/g,' plus ').replace(/\b(-?\d+)\/(\d+)\b/g,(_,n,d)=>sayNumber({n:Number(n),d:Number(d)})).replace(/\s+/g,' ').trim();
const hear=(text,label)=>btn('data-rm-read data-speak="'+esc(text)+'"',label);
const message={refused:T.refused,pending:T.pending,stale:T.stale,unknown:T.unreadable};
function visit(book,owner,create=true){let m=visits.get(book);if(!m&&create){m=new Map();visits.set(book,m);}let v=m?.get(owner);if(!v&&create){v={active:false,screen:'draft',key:null,card:null,serial:0,drafts:new Map(),cards:new Map(),page:0,pending:null,notice:'',bound:null,entry:null};m.set(owner,v);}return v;}
const current=v=>v.screen==='draft'?v.drafts.get(v.key):v.screen==='card'?v.cards.get(v.card):null;
function slot(source,work=null,caseId=null){const w=clone(work||newMixerWork(source));return {source:clone(source),work:w,caseId,page:'mix',previewOpen:false,checkOpen:false,referenceOpen:false,teachingPage:0,beforeHelp:'mix',cursors:{xn:w.pair?.x.n??0,xd:w.pair?.x.d??1,yn:w.pair?.y.n??0,yd:w.pair?.y.d??1},pendingText:null,folds:{},status:''};}
function add(v,a){a.ordinal=++v.serial;v.key='draft-'+v.serial;v.drafts.set(v.key,a);v.screen='draft';v.card=null;return a;}
export const mixerActive=(book,owner)=>okOwner(owner)&&route()&&visit(book,owner,false)?.active===true;
export function mixerEntry(){return '<aside class="rm-entry">'+btn('data-equality-mixer','Rule Mixer')+'<span>Make two clues work together.</span></aside>';}
export function bindMixerEntry(book,ctx={}){const owner=ctx.explorerId?.(),n=document.querySelector('[data-equality-mixer]');if(!n||!okOwner(owner))return;const v=visit(book,owner);v.entry=n;const chain=[];for(let p=n;p;p=p.parentNode)chain.push([p,p.parentNode]);n.addEventListener('click',()=>{if(v.entry!==n||!route()||n.disabled||!visible(n)||!n.isConnected||ctx.notebook?.()!==book||ctx.explorerId?.()!==owner||ctx.isActive?.()!==true||chain.some(([p,q])=>p.parentNode!==q))return;if(ctx.canEnter?.()!==true){ctx.refuse?.();return;}stopSpeech();v.active=true;if(v.screen!=='shelf'&&!current(v))add(v,slot(makeMixerSource(),null,'sum'));ctx.render();document.querySelector('#rm-heading')?.focus();});}
function visible(n){for(let p=n;p;p=p.parentElement){const c=getComputedStyle(p);if(p.hidden||p.getAttribute?.('aria-hidden')==='true'||c.display==='none'||['hidden','collapse'].includes(c.visibility))return false;if(p.tagName==='DETAILS'&&!p.open&&p!==n&&!p.querySelector(':scope>summary')?.contains(n))return false;}return true;}
const view=a=>({page:a.page,previewOpen:a.previewOpen,checkOpen:a.checkOpen,referenceOpen:a.referenceOpen,teachingPage:a.teachingPage});
const request=(v,a,fields={},destination=null)=>({origin:current(v),signature:bytes([current(v)?.source,current(v)?.work]),target:a,fields:{...view(a),work:a.work,cursors:clone(a.cursors),beforeHelp:a.beforeHelp,...fields},destination});
const pendingCurrent=v=>v.pending&&v.pending.origin===current(v)&&v.pending.signature===bytes([current(v)?.source,current(v)?.work]);
const qualify=(book,r,ctx)=>recordMixerDisplay(book,mixerDisplayPairs(r.target.source,r.fields.work,r.fields),ctx);
function syncCard(book,v){if(v.screen!=='card')return;const row=mixerSheetsView(book).items.find(r=>r.readable&&r.id===v.card),old=v.cards.get(v.card);if(!row){v.screen='shelf';v.card=null;v.pending=null;}else if(!old||old.raw!==row.raw||old.rawBytes!==bytes(row.raw)){const a=slot(row.raw.source,row.raw.work);Object.assign(a,{raw:row.raw,rawBytes:bytes(row.raw)});v.cards.set(v.card,a);v.pending=null;}}
export function prepareMixerDisplay(book,owner,ctx={}){const v=okOwner(owner)?visit(book,owner,false):null;if(!v||!mixerActive(book,owner))return {ok:true,changed:false};syncCard(book,v);const a=current(v);if(!a)return {ok:true,changed:false};const r=request(v,a),result=ctx.notebook?.()===book&&ctx.explorerId?.()===owner&&ctx.isActive?.()===true?qualify(book,r,ctx):{ok:false,changed:false};if(!result.ok){if(!pendingCurrent(v))v.pending=r;a.page='mix';a.previewOpen=false;a.checkOpen=false;a.referenceOpen=false;a.status=message.refused;}return result;}
function rowText(r){const terms=[];for(const [c,variable]of [[r.a,'x'],[r.b,'y']]){if(!c)continue;const val=(Math.abs(c)===1?'':Math.abs(c))+variable;terms.push((terms.length?(c<0?' − ':' + '):(c<0?'−':''))+val);}return (terms.join('')||'0')+' = '+num(r.c);}
function originals(s){return '<div class="rm-originals" aria-label="Both original equations">'+s.rows.map((r,i)=>'<p><span class="rm-row-label">'+esc(r.label)+'</span><strong>'+esc(rowText(r))+'</strong></p>').join('')+'</div>';}
function product(p){return '<span class="rm-product">'+esc('('+num(p.left)+') × ('+num(p.right)+') = '+num(p.value))+'</span>'+(p.pair?'<span class="rm-magnitude">'+esc('Magnitude '+p.pair[0]+' × '+p.pair[1]+' = '+p.pair[0]*p.pair[1])+'</span>':'');}
function mixHTML(m,title='Your mixture'){const z=T.zeroColumns;let text=m.kind==='contradiction'?'This mixture says 0 = '+num(m.row.c)+'. That cannot be true. The originals have no common pair.':m.kind==='tautology'?m.tautology==='line'?T.proportional:'Both factors are zero. '+T.tautology:m.kind==='one'?T.oneLetter:T.twoLetters;
return '<section class="rm-mixture"><div class="rm-scroll" tabindex="0" role="region" aria-label="Equation rows; scroll sideways if needed"><table><caption>'+esc(title)+' · every part of both rows</caption><thead><tr><th>Row</th><th>x column</th><th>y column</th><th>Right side</th></tr></thead><tbody>'+m.scaled.map((r,i)=>'<tr><th>'+esc(r.label)+' × '+esc(num(m.factors[i]))+'</th>'+r.products.map(p=>'<td>'+product(p)+'</td>').join('')+'</tr>').join('')+'<tr class="rm-result"><th>'+esc(m.op==='add'?'Add':'Subtract B')+'</th>'+m.columns.map(c=>'<td>'+esc(num(c.left)+(c.op==='subtract'?' − (':' + (')+num(c.right)+') = '+num(c.value))+'</td>').join('')+'</tr></tbody></table></div><p class="rm-equation">'+esc(rowText(m.row))+'</p><p>'+esc(z[m.zeroColumns])+'</p>'+m.lost.map(i=>'<p>Row '+(i===0?'A':'B')+' contributes no information because its factor is zero.</p>').join('')+'<p>'+esc(text)+'</p><p>'+esc(T.consequence)+'</p></section>';}
function pairProduct(p){return '<span>'+esc('('+num(p.coefficient)+') × ('+num(p.coordinate)+') = '+num(p.result))+'</span><span class="rm-numerator">Numerator: '+product(p.numerator)+'</span>';}
function checkHTML(c){return '<section class="rm-check"><h3>Check the same pair in BOTH originals</h3><p class="rm-equation">'+esc('('+num(c.pair.x)+', '+num(c.pair.y)+')')+'</p>'+c.rows.map(r=>'<section><h4>'+esc(r.label)+'</h4><div class="rm-check-products">'+pairProduct(r.ax)+pairProduct(r.by)+'</div><p>'+esc(num(r.ax.result)+' + ('+num(r.by.result)+') = '+num(r.sum)+'; the original asks for '+num(r.constant))+'. <strong>'+(r.fits?'Fits this original.':'Does not fit this original.')+'</strong></p></section>').join('')+'<p class="rm-fit">'+esc(T.checkKinds[c.kind])+'</p><p>'+esc(T.checkHelp)+'</p></section>';}
function crossHTML(label,c){return '<div class="rm-cross"><h4>'+esc(label)+'</h4>'+product(c.left)+product(c.right)+'<p>'+esc(num(c.left.value)+' − ('+num(c.right.value)+') = '+num(c.value))+'</p></div>';}
function referenceHTML(r){return '<section class="rm-reference"><h3>A worked route</h3><p>'+esc(T.reference)+'</p>'+crossHTML('Compare the variable columns',r.determinant)+(r.kind==='one'?'':crossHTML('Compare x and right-side columns',r.crossA)+crossHTML('Compare y and right-side columns',r.crossB))+(r.mix?'<h4>Multiply whole rows, then add</h4>'+mixHTML(r.mix,'Worked combination'):'<p>Each original has just one letter, so solve them separately.</p>')+r.solves.map(s=>'<p>'+esc(num(s.coefficient)+s.variable+' = '+num(s.constant)+'. Divide both sides by '+num(s.coefficient)+': '+s.variable+' = '+num(s.value))+'.</p>').join('')+(r.substitution?'<section><h4>Return to original '+(r.substitution.rowIndex===0?'A':'B')+'</h4>'+pairProduct(r.substitution.product)+'<p>'+esc(num(r.substitution.constant)+' − ('+num(r.substitution.product.result)+') = '+num(r.substitution.remainder))+'</p><p>'+esc('Divide by '+num(r.substitution.coefficient)+': '+r.substitution.otherVariable+' = '+num(r.substitution.value))+'.</p></section>':'')+(r.check?checkHTML(r.check):'')+'<p>'+esc(T.classification[r.kind])+'</p></section>';}
function rendered(a){return mixerDisplay(a.source,a.work,view(a));}
function teaching(a,d){const p=a.source.teaching[a.teachingPage],e=d?.teaching?.example;return '<h2 id="rm-task" tabindex="-1">How mixing works · '+(a.teachingPage+1)+' of '+a.source.teaching.length+'</h2><p>'+esc(p.words)+'</p>'+(e?'<section class="rm-example"><h3>A separate example</h3>'+originals({rows:e.rows})+(e.mix?mixHTML(e.mix,'Example mixture'):'')+(e.check?checkHTML(e.check):'')+(e.reference?referenceHTML(e.reference):'')+'</section>':d?.teaching?.unavailable?'<p>'+esc(T.pictureUnavailable)+'</p>':'')+'<div class="rm-actions">'+btn('data-rm-teach="-1"'+(a.teachingPage===0?' disabled':''),'Earlier')+btn('data-rm-teach="1"'+(a.teachingPage===a.source.teaching.length-1?' disabled':''),'Next')+btn('data-rm-close-help','Back to my work')+'</div>';}
function pageBody(a,ro){const d=rendered(a),w=a.work;if(a.page==='teaching')return teaching(a,d);if(a.page==='mix')return '<h2 id="rm-task" tabindex="-1">Make a mixture</h2><div class="rm-controls">'+select('data-rm-factor="0"','Multiply row A by',span(-3,3),w.factors[0],num,ro)+select('data-rm-factor="1"','Multiply row B by',span(-3,3),w.factors[1],num,ro)+select('data-rm-op','Combine rows',['add','subtract'],w.op,x=>x==='add'?'Add the rows':'Subtract B from A',ro)+'</div>'+btn('data-rm-preview',a.previewOpen?'Hide my mixture':'Show my mixture',true)+(d?.mix?mixHTML(d.mix):'<div class="rm-empty"><p>Choose factors, then show what the rows make together.</p><p>Every term—including the right side—gets multiplied.</p></div>');if(a.page==='pair')return '<h2 id="rm-task" tabindex="-1">Try a pair</h2><p>'+esc('Your mixture uses '+num(w.factors[0])+' times A '+(w.op==='add'?'plus':'minus')+' '+num(w.factors[1])+' times B.')+'</p><div class="rm-coordinates">'+['x','y'].map(k=>'<fieldset><legend>'+k+'</legend>'+select('data-rm-cursor="'+k+'n"','Numerator for '+k,span(-24,24),a.cursors[k+'n'],num,ro)+select('data-rm-cursor="'+k+'d"','Denominator for '+k,span(1,12),a.cursors[k+'d'],num,ro)+'</fieldset>').join('')+'</div>'+(!ro?'<div class="rm-actions">'+btn('data-rm-use-pair','Use this pair',true)+btn('data-rm-clear-pair','Clear my pair')+'</div>':'')+'<p class="rm-equation">'+(w.pair?esc('Proposed pair ('+num(w.pair.x)+', '+num(w.pair.y)+')'):'No pair proposed yet. The starting cursors are not an answer.')+'</p>'+btn('data-rm-check',a.checkOpen?'Hide the check':'Check in both originals')+(d?.check?checkHTML(d.check):'');return '<h2 id="rm-task" tabindex="-1">Explain for the next reader</h2><label>What would you tell the next reader?<textarea data-rm-note rows="4"'+(ro?' readonly':'')+'>'+esc(a.pendingText??w.note)+'</textarea></label><div class="rm-pending"'+(a.pendingText===null?' hidden':'')+'><p>'+esc(message.pending)+'</p>'+btn('data-rm-restore','Restore earlier words')+'</div>'+btn('data-rm-reference',a.referenceOpen?'Hide the worked route':'Show a worked route')+(d?.reference?referenceHTML(d.reference):'');}
function speakPage(a){const d=rendered(a);let html='';if(a.page==='teaching'){const t=d?.teaching;html=a.source.teaching[a.teachingPage].words+(t?.example?originals({rows:t.example.rows})+(t.example.mix?mixHTML(t.example.mix,'Example mixture'):'')+(t.example.check?checkHTML(t.example.check):'')+(t.example.reference?referenceHTML(t.example.reference):''):'');}else html=originals(a.source)+(d?.mix?mixHTML(d.mix):'')+(d?.check?checkHTML(d.check):'')+(d?.reference?referenceHTML(d.reference):'');const n=document.createElement('div');n.innerHTML=html;return words(n.textContent);}
function shelf(book,v){const r=mixerSheetsView(book),last=Math.max(0,Math.ceil(r.items.length/8)-1);v.page=Math.max(0,Math.min(v.page,last));return '<h2 id="rm-task" tabindex="-1">Kept sheets</h2>'+(r.status==='unavailable'?'<p>'+message.unknown+'</p>':r.items.length?r.items.slice(v.page*8,v.page*8+8).map(r=>r.readable?'<article>'+btn('data-rm-card="'+r.id+'"',r.raw.source.title)+'<p>A kept Rule Mixer sheet · '+(r.index+1)+'</p></article>':'<p>Earlier sheet '+(r.index+1)+'. '+esc(T.unreadable)+'</p>').join(''):'<p>No sheet kept yet. Unfinished work can be worth keeping.</p>')+'<div class="rm-actions">'+btn('data-rm-shelf-step="-1"'+(v.page===0?' disabled':''),'Previous sheets')+'<span>'+(v.page+1)+' / '+(last+1)+'</span>'+btn('data-rm-shelf-step="1"'+(v.page===last?' disabled':''),'More sheets')+'</div>';}
export function mixerPage(book,owner){const v=visit(book,owner);syncCard(book,v);const a=current(v),ro=v.screen==='card';return '<section class="rm-page" data-rm-root><header><div class="rm-actions">'+btn('data-rm-back','Equality Desk')+btn('data-rm-shelf','Kept sheets')+btn('data-rm-download','Download Notes')+'</div><h1 id="rm-heading" tabindex="-1">Rule Mixer</h1>'+(a?'<p class="rm-title">'+esc(a.source.title)+'</p><p>'+esc(a.source.question)+'</p>'+originals(a.source):'')+'</header>'+(v.screen==='shelf'?shelf(book,v):a?(ro?'<div class="rm-kept"><p>This kept sheet stays unchanged.</p>'+btn('data-rm-copy','Work on a copy',true)+'</div>':'')+'<nav class="rm-tabs" aria-label="Rule Mixer pages">'+[['mix','Mix'],['pair','Try a pair'],['explain','Explain']].map(([p,t])=>btn('data-rm-page="'+p+'" aria-current="'+(a.page===p?'page':'false')+'"',t)).join('')+'</nav>'+pageBody(a,ro)+'<div class="rm-actions rm-bottom">'+btn('data-rm-help','How mixing works')+hear(speakPage(a),'Read this page')+(!ro?btn('data-rm-keep','Keep this sheet',true):'')+'</div>':'')+'<p id="rm-status" role="status" tabindex="-1">'+esc(a?.status||v.notice||'')+'</p>'+(pendingCurrent(v)?btn('data-rm-retry','Retry'):'')+(v.helpCopy?btn('data-rm-confirm-copy','Open a new copy with this help'):'')+btn('data-rm-reopen hidden','Reopen saved sheets')+'<details data-rm-fold="drafts"'+(a?.folds.drafts?' open':'')+'><summary>Other demonstrations and working drafts</summary>'+select('data-rm-case','Choose a demonstration',['',...mixerCases.map(c=>c.id)],a?.caseId||'',id=>mixerCases.find(c=>c.id===id)?.title||'Kept source',ro)+select('data-rm-draft','Working drafts',[...v.drafts.keys()],v.key,k=>{const d=v.drafts.get(k);return d.source.title+' · draft '+d.ordinal;})+btn('data-rm-blank','New blank sheet')+'<p>Keep a sheet to include it in Notes. Working drafts wait in this open visit.</p></details>'+(a?'<details><summary>Why these rules?</summary><p>'+esc(a.source.story)+'</p><p>'+esc(T.domain)+'</p></details>':'')+'<details><summary>For grown-ups</summary><p>'+esc(T.grownups)+'</p></details><a href="#notes">Notes and download</a></section>';}
let removeNavigation=()=>{},navigation=()=>false;
export const guardMixerNavigation=()=>navigation();
export function bindRuleMixer(book,ctx={}){
 removeNavigation();removeNavigation=()=>{};navigation=()=>false;
 const owner=ctx.explorerId?.(),v=okOwner(owner)?visit(book,owner,false):null,root=document.querySelector('[data-rm-root]');
 if(!v||!root||typeof ctx.notebook!=='function'||typeof ctx.isActive!=='function'||typeof ctx.canExport!=='function'||typeof ctx.render!=='function')return;
 v.bound=root;const a=current(v),source=a?.source,screen=v.screen,key=v.key,card=v.card,chain=[],chains=new WeakMap();for(let n=root;n&&n!==document;n=n.parentNode)chain.push([n,n.parentNode]);
 let work=a?.work,sourceBytes=bytes(source),workBytes=bytes(work),raw=book.ruleMixerSheets,rawBytes=bytes(raw),present=own(book,'ruleMixerSheets');
 const connected=()=>visit(book,owner,false)===v&&ctx.explorerId()===owner&&v.bound===root&&route()&&ctx.notebook()===book&&ctx.isActive()===true&&root.isConnected&&document.querySelector('[data-rm-root]')===root;
 const attached=n=>chains.has(n)&&n.isConnected&&root.contains(n)&&chain.every(([p,q])=>p.parentNode===q)&&chains.get(n).every(([p,q])=>p.parentNode===q);
 const live=n=>{try{return connected()&&attached(n)&&visible(n)&&!n.disabled&&v.screen===screen&&v.key===key&&v.card===card&&current(v)===a&&a?.source===source&&a?.work===work&&bytes(source)===sourceBytes&&bytes(work)===workBytes&&sourceBytes!==null&&workBytes!==null&&own(book,'ruleMixerSheets')===present&&book.ruleMixerSheets===raw&&bytes(raw)===rawBytes&&rawBytes!==null&&(screen!=='card'||mixerSheetsView(book).items.some(r=>r.readable&&r.id===card&&r.raw===a.raw&&bytes(r.raw)===a.rawBytes));}catch{return false;}};
 const tell=t=>{v.notice=t;if(a)a.status=t;root.querySelector('#rm-status').textContent=t;};
 const stamp=()=>{work=a?.work;workBytes=bytes(work);sourceBytes=bytes(source);raw=book.ruleMixerSheets;rawBytes=bytes(raw);present=own(book,'ruleMixerSheets');};
 function stale(){if(connected()&&(own(book,'ruleMixerSheets')!==present||book.ruleMixerSheets!==raw||bytes(book.ruleMixerSheets)!==rawBytes)){tell(message.stale);const n=root.querySelector('[data-rm-reopen]');if(n.hidden){n.hidden=false;n.focus({preventScroll:true});return true;}}return false;}
 function guard(n){const c=[];for(let p=n;p&&p!==root;p=p.parentNode)c.push([p,p.parentNode]);chains.set(n,c);for(const type of ['click','change','input','keydown','focusin'])n.addEventListener(type,e=>{const recovery=e.target?.closest?.('[data-rm-reopen],[data-rm-restore],[data-rm-download]');if(!live(n)&&!(recovery&&connected()&&attached(recovery)&&visible(recovery)&&!recovery.disabled)){const first=stale();if(type==='keydown'&&e.key==='Tab'&&!first)return;e.preventDefault();e.stopImmediatePropagation();}},true);}
 guard(root);root.querySelectorAll('button,a,select,textarea,summary,details,[tabindex]').forEach(guard);
 const redraw=(target='#rm-task')=>{stopSpeech();ctx.render();const r=document.querySelector('[data-rm-root]'),n=r?.querySelector(target)||r?.querySelector('#rm-task,#rm-heading');if(n){n.focus({preventScroll:true});const b=n.getBoundingClientRect();if(b.top<0||b.bottom>innerHeight)n.scrollIntoView({block:'nearest'});}};
 function pending(){if(a?.pendingText!==null&&a?.pendingText!==undefined){tell(message.pending);return true;}return false;}
 function execute(r){if(!r)return false;const result=qualify(book,r,ctx);if(!result.ok){v.pending=r;tell(message.refused);root.querySelector('[data-rm-inline-retry]')?.remove();const n=document.createElement('button');n.type='button';n.className='secondary';n.dataset.rmInlineRetry='';n.textContent='Retry';n.addEventListener('click',()=>{if(live(n)&&pendingCurrent(v)&&!pending())execute(v.pending);});root.querySelector('#rm-status').after(n);guard(n);return false;}if(r.destination?.kind==='new')add(v,r.target);else if(r.destination?.kind==='draft'){v.key=r.destination.key;v.screen='draft';v.card=null;}Object.assign(r.target,r.fields);r.target.status='';v.notice='';v.pending=null;v.helpCopy=null;stamp();if(result.changed)ctx.save?.();redraw(r.focus||'#rm-task');return true;}
 function ask(fields={},flag=null){if(!a)return false;if(flag==='checkShown'&&!a.work.pair){tell('Choose a pair first. The starting cursors are not an answer.');return false;}if(screen==='card'&&flag&&!a.work[flag]){v.helpCopy={fields,flag};tell('This help can open on a new copy. Your kept sheet stays unchanged.');redraw('#rm-status');return false;}const w=flag?changeMixerWork(source,a.work,flag.replace('Shown',''),true):a.work;return execute(request(v,a,{...fields,work:w}));}
 const on=(selector,fn,target=null)=>root.querySelectorAll(selector).forEach(n=>n.addEventListener('click',()=>{if(!live(n)||pending())return;stopSpeech();const done=fn(n);if(done===true&&v.bound===root){stamp();redraw(target||'#rm-task');}}));
 const change=(selector,fn)=>root.querySelectorAll(selector).forEach(n=>n.addEventListener('change',()=>{if(!live(n)||pending())return;stopSpeech();fn(n);}));
 on('[data-rm-back]',()=>{v.active=false;ctx.render();document.querySelector('[data-equality-mixer]')?.focus();return false;});
 on('[data-rm-page]',n=>ask({page:n.dataset.rmPage}));
 on('[data-rm-preview]',()=>a.previewOpen?ask({previewOpen:false}):ask({previewOpen:true},'previewShown'));
 on('[data-rm-check]',()=>a.checkOpen?ask({checkOpen:false}):ask({checkOpen:true},'checkShown'));
 on('[data-rm-reference]',()=>a.referenceOpen?ask({referenceOpen:false}):ask({referenceOpen:true},'referenceShown'));
 on('[data-rm-help]',()=>ask({page:'teaching',beforeHelp:a.page==='teaching'?a.beforeHelp:a.page},'teachingShown'));
 on('[data-rm-teach]',n=>ask({teachingPage:a.teachingPage+Number(n.dataset.rmTeach)}));on('[data-rm-close-help]',()=>ask({page:a.beforeHelp}));
 change('[data-rm-factor]',n=>{const factors=[...a.work.factors];factors[Number(n.dataset.rmFactor)]=Number(n.value);const w=changeMixerWork(source,a.work,'factors',factors);const r=request(v,a,{work:w});r.focus='[data-rm-factor="'+n.dataset.rmFactor+'"]';if(!w||!execute(r)){n.value=a.work.factors[Number(n.dataset.rmFactor)];}});
 change('[data-rm-op]',n=>{const w=changeMixerWork(source,a.work,'op',n.value);const r=request(v,a,{work:w});r.focus='[data-rm-op]';if(!w||!execute(r))n.value=a.work.op;});
 change('[data-rm-cursor]',n=>{const k=n.dataset.rmCursor;a.cursors[k]=Number(n.value);v.pending=null;});
 on('[data-rm-use-pair]',()=>{const pair={x:fraction(a.cursors.xn,a.cursors.xd),y:fraction(a.cursors.yn,a.cursors.yd)},w=changeMixerWork(source,a.work,'pair',pair);if(!w)return false;const r=request(v,a,{work:w,cursors:{xn:pair.x.n,xd:pair.x.d,yn:pair.y.n,yd:pair.y.d}});r.focus='[data-rm-use-pair]';return execute(r);});
 on('[data-rm-clear-pair]',()=>{const w=changeMixerWork(source,a.work,'pair',null);return w&&execute(request(v,a,{work:w,checkOpen:false}));});
 on('[data-rm-copy]',()=>execute(request(v,slot(source,a.work),{}, {kind:'new'})));
 on('[data-rm-confirm-copy]',()=>{if(!v.helpCopy||!a||screen!=='card')return false;const {fields,flag}=v.helpCopy,t=slot(source,a.work);return execute(request(v,t,{...fields,work:changeMixerWork(t.source,t.work,flag.replace('Shown',''),true)}, {kind:'new'}));});
 on('[data-rm-retry]',()=>pendingCurrent(v)?execute(v.pending):false);
 on('[data-rm-blank]',()=>execute(request(v,slot(source||makeMixerSource(),null,a?.caseId||null),{}, {kind:'new'})));
 change('[data-rm-case]',n=>{const s=makeMixerSource(n.value);if(s)execute(request(v,slot(s,null,n.value),{}, {kind:'new'}));else n.value=a?.caseId||'';});
 change('[data-rm-draft]',n=>{const d=v.drafts.get(n.value);if(d)execute(request(v,d,{}, {kind:'draft',key:n.value}));});
 on('[data-rm-shelf]',()=>{v.screen='shelf';v.pending=null;v.helpCopy=null;return true;});on('[data-rm-shelf-step]',n=>{v.page+=Number(n.dataset.rmShelfStep);return true;});
 on('[data-rm-card]',n=>{const row=mixerSheetsView(book).items.find(r=>r.readable&&r.id===n.dataset.rmCard);if(!row)return false;const t=slot(row.raw.source,row.raw.work);Object.assign(t,{raw:row.raw,rawBytes:bytes(row.raw)});v.cards.set(row.id,t);v.card=row.id;v.screen='card';v.pending=null;v.helpCopy=null;return true;});
 on('[data-rm-keep]',()=>{if(screen!=='draft'||!a)return false;const id=keepMixerSheet(book,source,a.work,{canExport:ctx.canExport});if(!id){tell('This sheet could not be kept safely. Earlier sheets are unchanged. Download Notes before making room.');return false;}let result;try{result=ctx.save?.();}catch{}const row=mixerSheetsView(book).items.find(r=>r.readable&&r.id===id),t=slot(row.raw.source,row.raw.work);Object.assign(t,{raw:row.raw,rawBytes:bytes(row.raw),status:result?.enabled===true&&result.ok===true?'This sheet is kept.':result?.enabled===false?'Kept for this visit; saving is off.':'Kept for this visit; device saving is uncertain. Download Notes before leaving.'});v.cards.set(id,t);v.card=id;v.screen='card';v.pending=null;return true;},'#rm-status');
 root.querySelectorAll('[data-rm-download]').forEach(n=>n.addEventListener('click',()=>{if(connected()&&attached(n)&&visible(n)&&!n.disabled){stopSpeech();ctx.downloadNotes?.();}}));
 root.querySelectorAll('[data-rm-reopen]').forEach(n=>n.addEventListener('click',()=>{if(connected()&&attached(n)&&visible(n)&&!pending()){v.screen='shelf';v.pending=null;redraw();}}));
 const note=root.querySelector('[data-rm-note]');if(note&&!note.readOnly)note.addEventListener('input',()=>{if(!live(note))return;v.pending=null;const value=note.value,w=changeMixerWork(source,a.work,'note',value);if(w){a.work=w;a.pendingText=null;if(a.status===message.pending)tell('');stamp();note.removeAttribute('aria-invalid');root.querySelector('.rm-pending').hidden=true;}else{a.pendingText=value;note.setAttribute('aria-invalid','true');root.querySelector('.rm-pending').hidden=false;tell(message.pending);}});
 root.querySelector('[data-rm-restore]')?.addEventListener('click',()=>{const n=root.querySelector('[data-rm-restore]');if(!connected()||!attached(n)||!visible(n)||!window.confirm('Discard the visible unkept edits and restore the earlier words?'))return;a.pendingText=null;note.value=a.work.note;note.removeAttribute('aria-invalid');root.querySelector('.rm-pending').hidden=true;tell('Earlier words restored.');});
 root.querySelectorAll('[data-rm-fold]').forEach(n=>n.addEventListener('toggle',()=>{if(live(n)&&a)a.folds[n.dataset.rmFold]=n.open;}));
 const navigationBase=()=>ctx.notebook()===book&&ctx.explorerId()===owner&&v.bound===root&&root.isConnected&&document.querySelector('[data-rm-root]')===root&&a?.pendingText!==null&&a?.pendingText!==undefined;
 navigation=()=>{if(!navigationBase())return false;history.replaceState(null,'','#learn/math/equality');tell(message.pending);return true;};
 const pendingGuard=e=>{if(e.type==='keydown'&&!['Enter',' '].includes(e.key))return;if(!navigationBase()||!route())return;const allowed=e.target?.closest?.('[data-rm-note],[data-rm-restore],[data-rm-download]');if(allowed)return;if(e.target?.closest?.('button,a,input,select,summary')){e.preventDefault();e.stopImmediatePropagation();tell(message.pending);}};
 const unload=e=>{if(navigationBase()){e.preventDefault();e.returnValue='';}};
 document.addEventListener('click',pendingGuard,true);document.addEventListener('keydown',pendingGuard,true);window.addEventListener('beforeunload',unload);removeNavigation=()=>{document.removeEventListener('click',pendingGuard,true);document.removeEventListener('keydown',pendingGuard,true);window.removeEventListener('beforeunload',unload);navigation=()=>false;};
}
export function clearMixerGuards(){removeNavigation();removeNavigation=()=>{};navigation=()=>false;}
